theorem Set.image2_nonempty_iff.{u_1, u_3, u_5} : ∀ {α : Type u_1} {β : Type u_3} {γ : Type u_5} {f : α → β → γ}
  {s : Set α} {t : Set β}, (Set.image2 f s t).Nonempty ↔ s.Nonempty ∧ t.Nonempty :=
fun {α} {β} {γ} {f} {s} {t} ↦
  {
    mp := fun x ↦
      match x with
      | Exists.intro w (Exists.intro a ⟨ha, Exists.intro b ⟨hb, right⟩⟩) => ⟨Exists.intro a ha, Exists.intro b hb⟩,
    mpr := fun h ↦ Set.Nonempty.image2 h.left h.right }
